function law(){
var q=normalizeLawSearch((($("#qlaw")||{}).value||"").trim()),tokens=q.split(/\s+/).filter(Boolean),list=laws.filter(function(x){var text=normalizeLawSearch([x.id,x.article,x.category,x.title,x.description,x.bailNote].join(" "));return(cat==="Todas"||x.category===cat)&&tokens.every(function(term){return text.includes(term)})}),chosen=laws.filter(function(x){return sel.includes(x.id)}),reduction=Math.min(att.reduce(function(sum,id){return sum+({primario:30,advogado:20,confesso:10,comportamento:10}[id]||0)},0),40)/100,baseMonths=0,baseFine=0,bailTotal=0,bailRestricted=false;
function exclusion(x){if(sel.includes("25")&&["31","37"].includes(x.id))return"Art. "+x.id+" não soma com Art. 25.";if(sel.includes("26")&&["35","36"].includes(x.id))return"Art. "+x.id+" não soma com Art. 26.";if((sel.includes("50")||sel.includes("51"))&&x.id==="37")return"Art. 37 não soma com Art. 50 ou 51.";if((sel.includes("50")||sel.includes("51"))&&x.id==="35"&&!overrides.includes("ammo"))return"Com Art. 50/51, só soma fora da regra de munição 9 mm até 10 unidades.";if((sel.includes("50")||sel.includes("51"))&&x.id==="36"&&!overrides.includes("weapon"))return"Com Art. 50/51, só soma fora da regra de até 2 armas Colt.";return""}
var included=chosen.filter(function(x){return!exclusion(x)});included.forEach(function(x){baseMonths+=x[mode?"max":"min"];baseFine+=x.fine;if(x.bail==null)bailRestricted=true;else bailTotal+=x.bail});
var totalMonths=baseMonths*(1-reduction),fineTotal=Math.round(baseFine*(1-reduction)),hasHome=chosen.some(function(x){return x.id==="50"||x.id==="51"}),needAmmo=hasHome&&chosen.some(function(x){return x.id==="35"}),needWeapon=hasHome&&chosen.some(function(x){return x.id==="36"}),act="<div class='law-actions'><button data-a='penal-table'>Tabela de fianças e multas</button><button data-r='regras-roubo'>Regras de Roubo</button></div>";
var filters=cats.map(function(c){var n=c==="Todas"?laws.length:laws.filter(function(x){return x.category===c}).length;return"<button class='"+(cat===c?"selected":"")+"' data-a='cat' data-v='"+esc(c)+"'>"+esc(c)+" <small>"+n+"</small></button>"}).join("");
var cards=list.map(function(x){var chosenNow=sel.includes(x.id);return"<article class='penal-item "+(chosenNow?"is-selected":"")+"'><div class='penal-item-top'><span class='tag'>"+esc(x.article)+"</span><span class='penal-category'>"+esc(x.category)+"</span></div><h3>"+esc(x.title)+"</h3><p>"+esc(x.description)+"</p><div class='penal-facts'><span class='penal-sentence'><small>Pena em meses</small><b>"+x.min+(x.min===x.max?"":"–"+x.max)+" meses</b></span><span><small>Multa — redução</small><b>"+money(x.fine)+"</b></span><span><small>Fiança</small><b>"+(x.bail==null?esc(x.bailNote):money(x.bail))+"</b></span></div><button class='penal-select' data-a='penal-toggle' data-id='"+esc(x.id)+"'>"+(chosenNow?window.rotaIcon("check")+"Na soma · remover":window.rotaIcon("plus")+"Adicionar à soma")+"</button></article>"}).join("")||"<div class='empty penal-empty'>Nenhum artigo encontrado.</div>";
var selectedRows=chosen.map(function(x){var why=exclusion(x);return"<div class='selectedrow "+(why?"not-summed":"")+"'><span><b>"+esc(x.article)+" · "+esc(x.title)+"</b><strong class='penal-selected-months'>"+(mode?x.max:x.min)+" meses</strong><small>"+(why?esc(why):"Incluída no total")+"</small></span><button aria-label='Remover "+esc(x.title)+"' data-a='penal-toggle' data-id='"+esc(x.id)+"'>"+window.rotaIcon("x")+"</button></div>"}).join("")||"<p class='hint'>Adicione artigos para calcular a pena.</p>";
var reductions=[["primario","Réu primário","−30%"],["advogado","Advogado presente","−20%*"],["confesso","Réu confesso","−10%"],["comportamento","Bom comportamento","−10%"]].map(function(x){return"<label class='penal-check'><span>"+x[1]+" <b>"+x[2]+"</b></span><input type='checkbox' data-att='"+x[0]+"' "+(att.includes(x[0])?"checked":"")+"></label>"}).join("");
var overrideRows=(needAmmo?"<label class='penal-check exception-check'><span>Confirmo que a munição não é 9 mm ou passa de 10 unidades; permitir somar o Art. 35.</span><input type='checkbox' data-override='ammo' "+(overrides.includes("ammo")?"checked":"")+"></label>":"")+(needWeapon?"<label class='penal-check exception-check'><span>Confirmo que a arma não é Colt ou são mais de 2 armas; permitir somar o Art. 36.</span><input type='checkbox' data-override='weapon' "+(overrides.includes("weapon")?"checked":"")+"></label>":"");
return head("LEGACY ROLEPLAY · ROTA","Código Penal — Calculadora RP","Consulte os 52 artigos e 56 enquadramentos. Selecione os itens para somar a pena, multa e fiança.",act)+"<div class='penal-notice'>Tabela demonstrativa do servidor. As penas são expressas em meses. Aplicam-se as regras de não-somatória descritas na página Regras de Roubo.</div><div class='penal-layout'><section class='penal-catalog'><div class='penal-toolbar'><input id='qlaw' data-search placeholder='Buscar artigo, crime ou descrição...' value='"+esc(q)+"'><span>"+list.length+" resultado(s)</span></div><div class='penal-filters'>"+filters+"</div><div class='penal-grid'>"+cards+"</div></section><aside class='panel penal-calculator'><div class='panelhead'><div><small class='kicker'>DOSIMETRIA DE ROLEPLAY</small><h2>Cálculo da pena</h2></div><span>"+chosen.length+" selecionado(s)</span></div><div class='penal-mode'><span>Modo de pena</span><div><button data-a='mode' data-v='0' class='"+(!mode?"selected":"")+"'>Mínima</button><button data-a='mode' data-v='1' class='"+(mode?"selected":"")+"'>Máxima</button></div></div><div class='penal-reductions'><div class='penal-subhead'>Atenuantes <small>limite combinado: 40%</small></div>"+reductions+"<p class='hint'>* Aplique apenas conforme as regras do servidor.</p></div>"+(overrideRows?"<div class='penal-reductions'><div class='penal-subhead'>Exceções da regra de roubo</div>"+overrideRows+"</div>":"")+"<div class='penal-subhead'>Artigos selecionados</div><div class='penal-selected'>"+selectedRows+"</div><div class='penal-totals'><div class='penal-total-sentence'><span>Pena total</span><b>"+totalMonths.toLocaleString("pt-BR",{maximumFractionDigits:1})+" meses</b><small>Modo "+(mode?"máximo":"mínimo")+(reduction?" · redução "+Math.round(reduction*100)+"%":"")+"</small></div><div><span>Multa — redução</span><b>"+money(fineTotal)+"</b></div><div><span>Fiança total</span><b>"+money(bailTotal)+(bailRestricted?" + análise de delegado":"")+"</b></div></div><button class='penal-clear' data-a='penal-clear' "+(chosen.length?"":"disabled")+">Limpar cálculo</button></aside></div><p class='hint penal-disclaimer'>Conteúdo fictício para roleplay no MTA. Não é orientação jurídica, tabela oficial ou cálculo de pena real.</p>"
}
function robberyRules(){return head("PROCEDIMENTO OPERACIONAL · ROTA","Regras de Roubo","Exceções de não-somatória e condições especiais para o cálculo RP.","<button data-r='regras'>"+window.rotaIcon("arrow-left")+"Voltar ao Código Penal</button>")+"<div class='penal-notice'>Durante a execução do roubo, alguns artigos são absorvidos pela tipificação principal. Quando a regra permite exceção, marque a condição confirmada na calculadora para incluir o artigo secundário.</div><div class='robbery-rules-grid'><article class='robbery-rule-card'><span class='tag'>ART. 25</span><h2>Roubo à Caixinha / Caixa Eletrônico</h2><div class='robbery-exclusion'><b>Art. 31º — Posse de Dinheiro Sujo</b><p>Não pode ser somado quando decorre do mesmo roubo à Caixinha.</p></div><div class='robbery-exclusion'><b>Art. 37º — Tentativa de Fuga</b><p>Não pode ser somada durante a ação do roubo à Caixinha.</p></div></article><article class='robbery-rule-card'><span class='tag'>ART. 26</span><h2>Roubo a Estabelecimento</h2><div class='robbery-exclusion'><b>Art. 35º — Posse de Munição Ilegal</b><p>Não pode ser somada durante a ação de roubo ao estabelecimento.</p></div><div class='robbery-exclusion'><b>Art. 36º — Posse Ilegal de Armamento de Fogo</b><p>Não pode ser somada durante a ação de roubo ao estabelecimento.</p></div></article><article class='robbery-rule-card'><span class='tag'>ART. 50</span><h2>Invasão a Domicílio / Roubo a Residência</h2><div class='robbery-exclusion conditional'><b>Art. 35º — Posse de Munição Ilegal</b><p>Não soma para munição 9 mm até 10 unidades. Se for outro calibre ou mais de 10 unidades, pode somar.</p></div><div class='robbery-exclusion conditional'><b>Art. 36º — Posse Ilegal de Armamento de Fogo</b><p>Não soma para Colt até 2 armas. Se for outro armamento ou mais de 2 armas, pode somar.</p></div><div class='robbery-exclusion'><b>Art. 37º — Tentativa de Fuga</b><p>Não pode ser somada na ação de roubo a residências.</p></div></article><article class='robbery-rule-card'><span class='tag'>ART. 51</span><h2>Roubo a Covas</h2><div class='robbery-exclusion conditional'><b>Art. 35º — Posse de Munição Ilegal</b><p>Não soma para munição 9 mm até 10 unidades. Se for outro calibre ou mais de 10 unidades, pode somar.</p></div><div class='robbery-exclusion conditional'><b>Art. 36º — Posse Ilegal de Armamento de Fogo</b><p>Não soma para Colt até 2 armas. Se for outro armamento ou mais de 2 armas, pode somar.</p></div><div class='robbery-exclusion'><b>Art. 37º — Tentativa de Fuga</b><p>Não pode ser somada na ação de roubo a covas.</p></div></article></div><div class='robbery-note'><b>Observação</b><p>Outros artigos não listados nestas exceções podem ser somados se a infração correspondente tiver ocorrido durante a cena. Registre apenas fatos confirmados no RP.</p></div>"}
