async function refreshAdminDashboard(notify){if(previewRole||!window.ROTA_TICKETS.isAdmin()||adminRefreshBusy)return;adminRefreshBusy=true;try{var fresh=await window.ROTA_TICKETS.adminAction('admin-dashboard'),incoming=[];if(adminTab==='applications'){var applicationRows=await window.ROTA_TICKETS.adminAction('edital-applications-list');fresh.applications=applicationRows.rows||[]}if(adminSeenLoginIds===null)adminSeenLoginIds=new Set((fresh.logins||[]).map(function(x){return x.id}));else{incoming=(fresh.logins||[]).filter(function(x){return !adminSeenLoginIds.has(x.id)});(fresh.logins||[]).forEach(function(x){adminSeenLoginIds.add(x.id)});if(adminSeenLoginIds.size>100)adminSeenLoginIds=new Set(Array.from(adminSeenLoginIds).slice(-60))}var previousRoster=adminSnapshot&&Array.isArray(adminSnapshot.roster)?adminSnapshot.roster:[],rosterReadFailed=(fresh.dataIssues||[]).indexOf("efetivo ROTA")!==-1;if(rosterReadFailed||(!(fresh.roster||[]).length&&previousRoster.length))fresh.roster=previousRoster;adminSnapshot=fresh;if(notify&&incoming.length){incoming.reverse().forEach(function(x){var msg=x.display_name+' entrou no portal policial.';toast(msg);if('Notification'in window&&Notification.permission==='granted')new Notification('Login policial ROTA',{body:msg})})}if(page==='administracao'&&!document.querySelector("#app form[data-dirty='true']"))render()}catch(err){if(page==='administracao')loginMessage=err.message}finally{adminRefreshBusy=false}}
function startAdminPolling(){if(adminPollTimer)clearInterval(adminPollTimer);adminPollTimer=null;if(window.ROTA_TICKETS.isAdmin()){refreshAdminDashboard(false);adminPollTimer=setInterval(function(){refreshAdminDashboard(true)},15000)}}
async function runAdminAction(action,values,success){if(previewRole){toast("Prévia somente visual; nenhuma alteração foi enviada.");return}try{var result=await window.ROTA_TICKETS.adminAction(action,values||{});if(result.token)tokenIssued={name:result.displayName,token:result.token};await refreshAdminDashboard(false);render();toast(success||'Alteração salva.')}catch(err){loginMessage=err.message;render();toast(err.message)}}

async function checkPublicApplicationCooldown(input){if(previewRole)return;var form=input&&input.form;if(!form||!input.value.trim())return;var feedback=form.querySelector('[data-apply-feedback]'),button=form.querySelector("button[type='submit']"),playerId=input.value.trim();if(feedback)feedback.textContent='Consultando o prazo pelo ID/passaporte MTA…';try{var status=await window.ROTA_TICKETS.checkApplicationCooldown(playerId);if(input.value.trim()!==playerId)return;if(status.canApply){if(feedback)feedback.textContent='ID liberado para inscrição.';if(button)button.disabled=false;return}var when=status.availableAt?new Date(status.availableAt):new Date(Date.now()+(Number(status.remainingSeconds)||0)*1000),formatted=when.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'});if(feedback)feedback.textContent='Este ID já enviou uma inscrição. Você poderá enviar outra após '+formatted+'.';if(button)button.disabled=true;var wait=Math.max(0,Number(status.remainingSeconds)||0)*1000+1000;if(wait>0&&wait<2147480000)window.setTimeout(function(){if(input.isConnected&&input.value.trim()===playerId)checkPublicApplicationCooldown(input)},wait)}catch(error){if(input.value.trim()!==playerId)return;if(feedback)feedback.textContent='Não foi possível consultar agora. O servidor verificará o prazo ao enviar.';if(button)button.disabled=false}}
async function submitPublicApplication(form,values){if(previewRole){toast("Prévia somente visual; nenhuma alteração foi enviada.");return}var button=form.querySelector("button[type='submit']"),feedback=form.querySelector('[data-apply-feedback]'),edital=(data.editais||[]).find(function(x){return x.id===(values.editalId||selectedEditalId)});if(!edital){if(feedback)feedback.textContent='Escolha um edital aberto antes de enviar a ficha.';return}if(button){button.disabled=true;button.textContent='Enviando…'}if(feedback)feedback.textContent='Registrando sua inscrição…';try{var result=await window.ROTA_TICKETS.submitApplication({editalId:edital.id,editalTitle:edital.title,fullName:values.fullName,serverRg:values.serverRg,characterName:values.characterName,characterId:values.characterId,realAge:values.realAge,rpExperience:values.rpExperience,policeExperience:values.policeExperience,roleplayDefinition:values.roleplayDefinition,metagamingDefinition:values.metagamingDefinition,powergamingDefinition:values.powergamingDefinition,whyPmce:values.whyPmce,characterStory:values.characterStory});data.apps.unshift({name:values.characterName,id:values.characterId,editalId:edital.id,editalTitle:edital.title,applicationId:result.id,createdAt:result.createdAt||new Date().toISOString()});save();selectedEditalId='';editalTab='mine';editalQuery='';page='editais';location.hash=page;render();toast('Inscrição registrada. Você poderá se inscrever novamente após 48 horas.')}catch(error){if(feedback)feedback.textContent=error.message;if(button){button.disabled=error.status===429;button.textContent='Enviar ficha de recrutamento'}toast('Não foi possível enviar: '+error.message)}}function formatEditalDate(value){if(!value)return "A divulgar";var d=new Date(value);return Number.isNaN(d.getTime())?"A divulgar":d.toLocaleString("pt-BR",{dateStyle:"short",timeStyle:"short"})}
function isEditalOpen(x){var now=Date.now();return x.status==="Inscrições abertas"&&(!x.opensAt||new Date(x.opensAt).getTime()<=now)&&(!x.closesAt||new Date(x.closesAt).getTime()>=now)}
function editalResults(id){var x=(data.editais||[]).find(function(item){return item.id===id}),m=$("#modal");if(!x)return;var rows=(x.results||[]).map(function(r){return "<div class='edital-result-row'><b>"+esc(r.name)+"</b><span class='tag "+(r.status==="Aprovado"?"green":"")+"'>"+esc(r.status)+"</span></div>"}).join("")||"<div class='empty'>O comando ainda não publicou o resultado deste edital.</div>";m.innerHTML="<div class='modalhead'><div><small class='kicker'>PROCESSO SELETIVO</small><h2>Resultado · "+esc(x.title)+"</h2></div><button type='button' data-a='close' aria-label='Fechar'>"+window.rotaIcon("x")+"</button></div><div class='pad edital-results'>"+rows+"</div>";m.showModal()}
function editalCard(x,application){var hasApplication=!!application,isOpen=isEditalOpen(x),action=(hasApplication?"<span class='edital-submitted'>"+window.rotaIcon("check")+"Inscrição enviada</span>":isOpen?"<button data-a='edital-apply' data-id='"+esc(x.id)+"'>Realizar inscrição</button>":"")+(contentAdmin()?"<button type='button' class='danger' data-a='del-edital' data-id='"+esc(x.id)+"'>Remover edital</button>":"");return "<article class='edital-card'><div class='edital-card-top'><span class='edital-state "+(hasApplication?"is-submitted":"is-open")+"'>"+(hasApplication?"Inscrição enviada":isOpen?"Inscrições abertas":new Date(x.opensAt).getTime()>Date.now()?"Agendado":"Encerrado")+"</span><span class='edital-count'>"+(hasApplication?"Inscrição neste dispositivo":"Sem login · ficha individual")+"</span></div><h2>"+esc(x.title)+"</h2><p class='edital-summary'>"+esc(x.summary||"Confira os detalhes deste processo seletivo da ROTA no Legacy Roleplay.")+"</p><div class='edital-dates'><span><small>ABERTURA</small><b>"+formatEditalDate(x.opensAt)+"</b></span><span><small>ENCERRAMENTO</small><b>"+formatEditalDate(x.closesAt)+"</b></span></div><button class='edital-results-link' type='button' data-a='edital-results' data-id='"+esc(x.id)+"'>Ver aprovados e reprovados</button><div class='edital-card-actions'>"+action+"</div></article>"}function editaisPage(){var all=data.editais||[],open=all.filter(isEditalOpen),my=(data.apps||[]).filter(function(a){return a.editalId}).map(function(a){var x=all.find(function(item){return item.id===a.editalId});return x?Object.assign({},x,{application:a}):null}).filter(Boolean),source=editalTab==="mine"?my:(contentAdmin()?all:open),q=editalQuery.trim().toLocaleLowerCase("pt-BR"),list=source.filter(function(x){return (x.title+" "+(x.summary||"")).toLocaleLowerCase("pt-BR").includes(q)}),cards=list.map(function(x){return editalCard(x,!!x.application)}).join("");return head("OPORTUNIDADES DA UNIDADE","Recrutamento","Editais e processo seletivo para entrar na ROTA: veja o que está aberto, os prazos e envie sua ficha.")+"<section class='panel edital-panel'><div class='edital-heading'><div><small class='kicker'>MURAL DA UNIDADE</small><h2>Processos seletivos</h2><p>Editais publicados pela administração da ROTA.</p></div><div class='edital-tabs' role='tablist' aria-label='Visualizar editais'><button type='button' role='tab' aria-selected='"+(editalTab==="open")+"' class='"+(editalTab==="open"?"selected":"")+"' data-a='edital-tab' data-v='open'>Editais abertos <span>"+open.length+"</span></button><button type='button' role='tab' aria-selected='"+(editalTab==="mine")+"' class='"+(editalTab==="mine"?"selected":"")+"' data-a='edital-tab' data-v='mine'>Minhas inscrições <span>"+my.length+"</span></button></div></div><div class='edital-toolbar'><label for='qeditais'>Buscar edital</label><input id='qeditais' type='search' value='"+esc(editalQuery)+"' placeholder='Título ou descrição do edital' autocomplete='off'></div><div class='edital-grid'>"+(cards||"<div class='empty edital-empty'>"+(editalTab==="mine"?"Você ainda não enviou uma inscrição neste navegador.":open.length?"Nenhum edital corresponde à sua busca.":contentNote("editais","Não há editais abertos no momento. Volte em breve para conferir novas oportunidades."))+"</div>")+"</div><p class='edital-disclaimer'>As fichas enviadas ficam disponíveis para análise da equipe. A aba Minhas inscrições registra os envios feitos neste navegador.</p></section>"}

