function citizenBo(){var activeId=localStorage.getItem("rota-bo-active"),report=(data.reports||[]).find(function(x){return x.id===activeId});if(report){var status=report.status||"Pendente",pending=status==="Pendente"||status==="Recebido",stateText=status==="Aceito"?"B.O. aceito":status==="Recusado"?"Pedido recusado":"Aguardando aprovação",stateClass=status==="Aceito"?"accepted":status==="Recusado"?"rejected":"pending",message=status==="Aceito"?"Seu B.O. foi aceito por um policial. Aguarde o atendimento; ele pode levar até 10 minutos. Se precisar de contato, a equipe falará com você pelo Discord informado.":status==="Recusado"?"Um policial recusou o pedido. Se precisar, envie uma nova solicitação com os dados completos.":"Seu pedido aguarda análise de um policial. O atendimento pode demorar até 10 minutos. A equipe poderá falar com você pelo Discord informado.";return head("ATENDIMENTO AO CIDADÃO","Solicitar B.O.","Acompanhe a análise do seu pedido.")+"<section class='panel support-panel'><div class='panelhead'><div><h2>Solicitação "+esc(report.id)+"</h2><small>Enviada em "+esc(report.created||"—")+"</small></div><button type='button' data-a='bo-new'>Abrir outro B.O.</button></div><div class='support-ticket-state "+stateClass+"'><b>"+stateText+"</b><p>"+message+"</p></div><div class='support-ticket-fields'><div><small>USUÁRIO DISCORD</small><b>"+esc(report.discord||"—")+"</b></div><div><small>PASSAPORTE LEGACY</small><b>"+esc(report.player||"—")+"</b></div><div><small>MOTIVO DO B.O.</small><b>"+esc(report.category||report.title||"—")+"</b></div><div class='ticket-reason'><small>RELATO DO OCORRIDO</small><p>"+esc(report.detail||"—")+"</p></div></div>"+ticketKeyBox(report)+"<small class='hint'>O status desta página é atualizado quando um policial decidir o pedido.</small></section>"}return head("ATENDIMENTO AO CIDADÃO","Solicitar B.O.","Envie um pedido para análise da equipe policial no roleplay.")+"<section class='panel form-panel'><div class='panelhead'><h2>Novo pedido de B.O.</h2></div><form id='citizenBo' class='form'><label>Usuário Discord *<input name='discord' required maxlength='100' placeholder='Seu usuário ou @ no Discord'></label><label>Passaporte Legacy *<input name='player' required maxlength='40' placeholder='Seu passaporte/ID no servidor'></label><fieldset class='full bo-category-fieldset'><legend>Motivo do B.O. <span>Escolha a categoria que melhor descreve a cena</span></legend><div class='bo-category-grid'>"+citizenBoCategories()+"</div></fieldset><label class='full'>Relato do ocorrido *<textarea name='detail' required maxlength='2000' placeholder='Conte o que aconteceu durante a cena de RP.'></textarea></label><div class='notice full'>A solicitação precisa ser aceita por um policial. Aguarde para ser atendido; o tempo de espera pode chegar a 10 minutos. Se precisar de contato, a equipe falará com você pelo Discord informado.</div><small class='full hint'>Use apenas dados e situações fictícias do servidor. Este formulário não registra ocorrência oficial.</small><button class='primary full'>Enviar pedido de B.O.</button></form></section>"+ticketLookupForm("bo")}function ombudsmanRail(){return "<aside class='ombudsman-aside'><div class='ombudsman-rail-eyebrow'><i></i> CANAL CIDADÃO · ROTA</div><span class='ombudsman-rail-mark' aria-hidden='true'>◉</span><h2>Uma conversa clara ajuda a cidade.</h2><p>Envie seu relato com calma. A equipe da Ouvidoria vai analisar o chamado dentro do roleplay.</p><div class='ombudsman-flow'><div><span>01</span><p><b>Identifique seu personagem</b><small>Informe passaporte e nome na Legacy.</small></p></div><div><span>02</span><p><b>Explique o motivo</b><small>Conte o que aconteceu de forma objetiva.</small></p></div><div><span>03</span><p><b>Aguarde a análise</b><small>O ticket fica pendente até a equipe avaliar.</small></p></div></div><div class='ombudsman-privacy'><b>AMBIENTE DE ROLEPLAY</b><small>Use apenas informações fictícias do servidor. Não envie dados pessoais reais.</small></div></aside>"}
function citizenOmbudsman(){var activeId=localStorage.getItem("rota-support-active"),ticket=(data.supportTickets||[]).find(function(x){return x.id===activeId});if(ticket){var status=ticket.status||"Pendente",statusText=status==="Aceito"?"Chamado aceito":status==="Recusado"?"Chamado recusado":"Aguardando análise",statusClass=status==="Aceito"?"accepted":status==="Recusado"?"rejected":"pending";return head("CANAL DE ATENDIMENTO","Ouvidoria","Acompanhe a análise do seu ticket.")+"<section class='ombudsman-shell ombudsman-shell-track'>"+ombudsmanRail()+"<section class='panel support-panel ombudsman-form-panel'><div class='panelhead ombudsman-panelhead'><div><small class='kicker'>ACOMPANHAMENTO DO CHAMADO</small><h2>Ticket "+esc(ticket.id)+"</h2><small>Enviado em "+esc(ticket.created||"—")+"</small></div><button type='button' data-a='support-new'>Abrir outro ticket</button></div><div class='support-ticket-state "+statusClass+"'><b>"+statusText+"</b><p>"+(status==="Pendente"?"A equipe da Ouvidoria analisará as informações enviadas.":status==="Aceito"?"A equipe aceitou seu contato. Acompanhe as orientações pelos canais da cidade.":"A Ouvidoria recusou este chamado.")+"</p></div><div class='support-ticket-fields'><div><small>USUÁRIO DISCORD</small><b>"+esc(ticket.discord)+"</b></div><div><small>PASSAPORTE / ID IN-GAME</small><b>"+esc(ticket.player)+"</b></div><div><small>NOME PASSAPORTE LEGACY</small><b>"+esc(ticket.legacyName)+"</b></div><div class='ticket-reason'><small>MOTIVO DO CONTATO</small><p>"+esc(ticket.reason)+"</p></div></div>"+ticketKeyBox(ticket)+"<small class='hint'>O status desta página é atualizado quando a Ouvidoria analisar o chamado. Só a equipe autorizada vê os chamados.</small></section></section>"}return head("CANAL DE ATENDIMENTO","Ouvidoria","Um canal direto para dúvidas, sugestões e relatos da comunidade Legacy.")+"<section class='ombudsman-shell'>"+ombudsmanRail()+"<section class='panel form-panel ombudsman-form-panel'><div class='panelhead ombudsman-panelhead'><div><small class='kicker'>NOVO ATENDIMENTO</small><h2>Abrir ticket para a Ouvidoria</h2></div><span class='ombudsman-secure'>Canal da comunidade</span></div><form id='supportStart' class='form ombudsman-form'><label>Usuário Discord *<input name='discord' required maxlength='100' placeholder='Seu usuário ou @ no Discord'></label><label>Passaporte / ID in-game *<input name='player' required maxlength='40' placeholder='Seu passaporte ou ID no MTA'></label><label class='full'>Nome Passaporte Legacy *<input name='legacyName' required maxlength='100' placeholder='Nome do seu personagem na Legacy'></label><label class='full'>Motivo de abrir o ticket *<textarea name='reason' required maxlength='1500' placeholder='Escreva o motivo do contato com a Ouvidoria...'></textarea></label><small class='full hint'>Informe somente dados do seu personagem no roleplay. O envio ficará pendente até a equipe analisar.</small><button class='primary full ombudsman-submit'>Enviar ticket</button></form></section></section>"+ticketLookupForm("ouvidoria")}
