var waiting=data.reports.filter(isWaiting),ombud=(data.supportTickets||[]).filter(isWaiting).length,wanted=data.wanted||[],ops=(data.ops||[]).filter(function(x){return x.status!=="Concluída"}),active=(rosterSeen||[]).filter(function(x){return x.status==="Ativo"}).length;
