var actions="<div class='actions'>"+(contentAdmin()?"<button type='button' data-a='open' data-type='announcement'>"+window.rotaIcon("megaphone")+"Publicar comunicado</button><button type='button' data-a='open' data-type='edital'>"+window.rotaIcon("clipboard-list")+"Publicar edital</button>":"")+"<button type='button' class='primary' data-r='prisoes'>"+window.rotaIcon("lock")+"Registrar prisão</button></div>";
var opsPanel="<section class='panel dash-ops'><div class='panelhead'><h2>Operações em andamento</h2><button type='button' data-r='operacoes'>Ver quadro</button></div>"+(boardStatus("ops",ops.length)||(ops.length?"":"<div class='empty'>Nenhuma operação em andamento. O quadro de operações mostra as próximas assim que forem cadastradas.</div>")||"<ul class='dash-list'>"+ops.slice(0,5).map(function(x){return"<li><span><b>"+esc(x.title)+"</b><small>"+esc([x.zone,x.leader].filter(Boolean).join(" · "))+"</small></span>"+pill(x.status||"Em andamento")+"</li>"}).join("")+"</ul>")+"</section>";
var queue="<div class='metric-grid police-metrics'><button type='button' data-r='bo-inbox' class='"+(waiting.length?"hot":"")+"'><b>"+waiting.length+"</b><small>B.O. aguardando</small></button><button type='button' data-r='ouvidoria-inbox' class='"+(ombud?"hot":"")+"'><b>"+ombud+"</b><small>Ouvidoria aguardando</small></button><button type='button' data-r='efetivo'><b>"+(rosterSeen===null?"…":active)+"</b><small>Integrantes ativos</small></button><button type='button' data-r='procurados'><b>"+wanted.length+"</b><small>Procurados no mural</small></button></div>";
var list=waiting.slice().reverse().slice(0,6),rows=list.map(function(x){return"<tr><td><span class='prefixo'>"+esc(x.id)+"</span></td><td><b>"+esc(x.category||"Outro")+"</b><small>Passaporte "+esc(x.player||"—")+"</small></td><td class='muted'>"+esc(x.created||"")+"</td><td><i class='tag gold'>Aguardando</i></td></tr>"}).join("");
var table="<section class='panel dash-queue'><div class='panelhead'><div><h2>B.O. aguardando decisão</h2><p>Os mais antigos primeiro.</p></div><button type='button' data-r='bo-inbox'>Abrir caixa</button></div>"+(rows?"<div class='table-wrap'><table><thead><tr><th>Protocolo</th><th>Motivo</th><th>Enviado</th><th>Situação</th></tr></thead><tbody>"+rows+"</tbody></table></div>":"<div class='empty'>Nenhum B.O. aguardando. Os novos pedidos aparecem aqui assim que o cidadão envia.</div>")+"</section>";
var wantedList="<section class='panel dash-wanted'><div class='panelhead'><h2>Procurados</h2><button type='button' data-r='procurados'>Ver mural</button></div>"+(wanted.length?"<ul class='dash-list'>"+wanted.slice(0,5).map(function(x){return"<li><span><b>"+esc(x.title)+"</b><small>"+esc(x.detail||"")+"</small></span>"+(x.person?"<span class='prefixo'>"+esc(x.person)+"</span>":"")+"</li>"}).join("")+"</ul>":"<div class='empty'>Nenhum procurado no mural.</div>")+"</section>";
